const { requireWithFallback } = require('./require-package');

const {
  SYNC_MODES,
  EXPORT_FAILURE_BEHAVIORS,
  THEME_SYNC_MODES,
  MISSING_TEMPLATE_POLICIES
} = requireWithFallback(
  require,
  '@synclistic/types',
  '../../types'
);
const { VALID_SYNC_OBJECT_TYPES, getSyncOrder } = require('./dependencies');
const { SyncCoreError } = require('./errors');

function normalizeStoreName(store) {
  if (!store) {
    return null;
  }

  if (typeof store === 'string') {
    return store.trim() || null;
  }

  return store.store_name || store.name || null;
}

function normalizeSyncMode(config, errors) {
  if (config.createOnly && config.updateOnly) {
    errors.push({
      code: 'CONFLICTING_SYNC_MODE_FLAGS',
      message: '--create-only and --update-only cannot be used together',
      field: 'syncMode'
    });
    return null;
  }

  let syncMode = (config.syncMode || 'create-and-update').toLowerCase();

  if (config.createOnly) {
    syncMode = 'create';
  }

  if (config.updateOnly) {
    syncMode = 'update';
  }

  if (!SYNC_MODES.includes(syncMode)) {
    errors.push({
      code: 'INVALID_SYNC_MODE',
      message: `Invalid sync mode: ${syncMode}`,
      field: 'syncMode',
      meta: { allowedValues: SYNC_MODES }
    });
    return null;
  }

  return syncMode;
}

function normalizeObjects(objects, errors) {
  const normalizedObjects = Array.isArray(objects)
    ? objects.map((objectType) => String(objectType).toLowerCase())
    : [];

  const invalidObjects = normalizedObjects.filter(
    (objectType) => !VALID_SYNC_OBJECT_TYPES.includes(objectType)
  );

  if (invalidObjects.length > 0) {
    errors.push({
      code: 'INVALID_OBJECT_TYPES',
      message: `Invalid object types: ${invalidObjects.join(', ')}`,
      field: 'objects',
      meta: { invalidObjects, allowedValues: VALID_SYNC_OBJECT_TYPES }
    });
  }

  if (normalizedObjects.length === 0) {
    errors.push({
      code: 'MISSING_OBJECTS',
      message: 'At least one object type must be selected',
      field: 'objects'
    });
  }

  return normalizedObjects;
}

function validateSyncConfig(config) {
  const errors = [];
  const normalizedObjects = normalizeObjects(config.objects, errors);
  const syncMode = normalizeSyncMode(config, errors);
  const exportFailureBehavior = String(
    config.exportFailureBehavior || config.onExportFailure || 'fail'
  ).toLowerCase();
  const themeSyncMode = String(config.themeSyncMode || 'dependencies').toLowerCase();
  const missingTemplatePolicy = String(
    config.missingTemplatePolicy || 'clear'
  ).toLowerCase();

  if (!EXPORT_FAILURE_BEHAVIORS.includes(exportFailureBehavior)) {
    errors.push({
      code: 'INVALID_EXPORT_FAILURE_BEHAVIOR',
      message: `Invalid export failure behavior: ${exportFailureBehavior}`,
      field: 'exportFailureBehavior',
      meta: { allowedValues: EXPORT_FAILURE_BEHAVIORS }
    });
  }

  if (!THEME_SYNC_MODES.includes(themeSyncMode)) {
    errors.push({
      code: 'INVALID_THEME_SYNC_MODE',
      message: `Invalid theme sync mode: ${themeSyncMode}`,
      field: 'themeSyncMode',
      meta: { allowedValues: THEME_SYNC_MODES }
    });
  }

  if (!MISSING_TEMPLATE_POLICIES.includes(missingTemplatePolicy)) {
    errors.push({
      code: 'INVALID_MISSING_TEMPLATE_POLICY',
      message: `Invalid missing template policy: ${missingTemplatePolicy}`,
      field: 'missingTemplatePolicy',
      meta: { allowedValues: MISSING_TEMPLATE_POLICIES }
    });
  }

  const sourceName = normalizeStoreName(config.source);
  const destinationName = normalizeStoreName(config.destination);
  if (
    sourceName &&
    destinationName &&
    sourceName.toLowerCase() === destinationName.toLowerCase()
  ) {
    errors.push({
      code: 'SOURCE_DESTINATION_MATCH',
      message: 'Source and destination stores cannot be the same',
      field: 'destination'
    });
  }

  const isProductIdSync = Boolean(
    config.sourceProductIds || config.destinationProductIds
  );

  if (isProductIdSync) {
    if (!sourceName || !destinationName) {
      errors.push({
        code: 'PRODUCT_ID_SYNC_REQUIRES_STORES',
        message: 'Product ID sync requires both source and destination stores',
        field: 'source'
      });
    }

    if (!config.sourceProductIds) {
      errors.push({
        code: 'MISSING_SOURCE_PRODUCT_IDS',
        message: 'Product ID sync requires source product IDs',
        field: 'sourceProductIds'
      });
    }

    const nonProductObjects = normalizedObjects.filter(
      (objectType) => objectType !== 'products'
    );

    if (nonProductObjects.length > 0) {
      errors.push({
        code: 'PRODUCT_ID_SYNC_PRODUCTS_ONLY',
        message: 'Product ID sync can only be used with products',
        field: 'objects',
        meta: { invalidObjects: nonProductObjects }
      });
    }
  }

  if (errors.length > 0) {
    return {
      valid: false,
      normalizedConfig: null,
      errors
    };
  }

  let orderedObjects;
  try {
    orderedObjects = getSyncOrder(normalizedObjects);
  } catch (error) {
    if (error instanceof SyncCoreError) {
      return {
        valid: false,
        normalizedConfig: null,
        errors: [
          {
            code: error.code,
            message: error.message,
            field: 'objects',
            meta: error.details
          }
        ]
      };
    }

    throw error;
  }

  const normalizedConfig = {
    ...config,
    objects: normalizedObjects,
    orderedObjects,
    syncMode,
    createOnly: syncMode === 'create',
    updateOnly: syncMode === 'update',
    cleanDestination: Boolean(config.cleanDestination),
    exportBeforeSync: Boolean(config.exportBeforeSync || config.export),
    exportFailureBehavior,
    themeSyncMode,
    destinationThemeId: config.destinationThemeId || null,
    missingTemplatePolicy,
    source: config.source || null,
    destination: config.destination || null
  };

  return {
    valid: true,
    normalizedConfig,
    errors: []
  };
}

module.exports = {
  validateSyncConfig
};
